.hf-button{border:1px solid transparent;border-radius:11px;padding:10px 14px;min-height:41px;display:inline-flex;align-items:center;justify-content:center;gap:8px;background:var(--hf-navy);color:white;font-weight:700;transition:transform .12s,background .12s;white-space:nowrap}.hf-button:hover{background:#3b3a50;transform:translateY(-1px)}.hf-button-primary{background:var(--hf-orange);color:#fff}.hf-button-primary:hover{background:#a9612d}.hf-button-secondary{background:#fffdf9;color:var(--hf-navy);border-color:var(--hf-border)}.hf-button-secondary:hover{background:var(--hf-cream)}.hf-button-danger{background:#fff1ee;color:#9a352b;border-color:#f1d1cb}.hf-button-danger:hover{background:#ffe4df}.hf-button-success{background:#e8f5ed;color:#1f7047;border-color:#cce8d7}.hf-button-small{min-height:32px;padding:6px 9px;border-radius:9px;font-size:12px}.hf-select,.hf-input,.hf-textarea{width:100%;min-width:0;border:1px solid var(--hf-border);border-radius:11px;background:#fffdf9;color:var(--hf-navy);padding:10px 12px;min-height:41px}.hf-textarea{min-height:90px;resize:vertical;line-height:1.55}.hf-field{display:grid;gap:6px;font-size:12px;font-weight:700;color:var(--hf-navy)}.hf-help{font-weight:400;font-size:11px;color:var(--hf-muted);line-height:1.45}.hf-field-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.hf-span-2{grid-column:1/-1}.hf-check{display:flex;align-items:center;gap:9px;font-weight:600;font-size:13px}.hf-check input{width:17px;height:17px;accent-color:var(--hf-orange)}
