/* ==========================================================================
   HALAL FOOD ADMIN — modern analytics workspace
   A neutral dashboard-only palette, intentionally independent of storefront
   branding. High-contrast surfaces and saturated data colors are used for
   dense, at-a-glance analytics.
   ========================================================================== */
:root{
 --hf-navy:#E6EDF8;
 --hf-orange:#5B7CFA;
 --hf-cream:#0B1322;
 --hf-paper:#111C2E;
 --hf-muted:#9AAAC0;
 --hf-border:#283750;
 --hf-blue:#4F7CFF;
 --hf-green:#10B981;
 --hf-red:#F05274;
 --hf-yellow:#F59E0B;
 --hf-purple:#9B6DFF;
 --hf-shadow:0 18px 46px rgba(0,0,0,.24);
 --hf-radius:16px;
 color-scheme:dark;
}
html{background:#0A1020;scroll-behavior:smooth}
body{
 background:
  radial-gradient(900px 440px at 8% -10%,rgba(79,124,255,.13),transparent 68%),
  radial-gradient(820px 400px at 100% 0%,rgba(155,109,255,.08),transparent 67%),
  #0A1020;
 color:#E6EDF8;
 font-family:Inter,"Segoe UI Variable","Segoe UI",ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,sans-serif;
 font-size:14px;line-height:1.55;
 -webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility;
}
::selection{background:rgba(79,124,255,.38);color:#fff}
a{color:#9CB7FF}
a:hover{color:#C8D6FF}
button,input,select,textarea{font-family:inherit}
button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{
 outline:2px solid #7CA0FF;outline-offset:3px
}
.admin-app{background:transparent;grid-template-columns:258px minmax(0,1fr)}
.admin-sidebar{
 background:linear-gradient(180deg,#080E1B 0%,#0B1424 100%);
 border-right:1px solid #223149;
 color:#E6EDF8;padding:24px 15px;
 box-shadow:12px 0 36px rgba(0,0,0,.12);
}
.admin-brand{border-bottom-color:#24344D;padding:2px 10px 20px}
.admin-brand img{background:#F7F9FC;border:1px solid #E2E8F0;border-radius:12px}
.admin-brand strong{font-size:16px;font-weight:760;letter-spacing:-.035em}
.admin-brand small{color:#899AB3;font-size:11px;letter-spacing:.035em}
.admin-nav-group{gap:5px}
.admin-nav-label{color:#70829C;font-size:10px;letter-spacing:.16em;padding:0 13px 8px}
.admin-nav-link{
