.kpi-icon-orange{background:rgba(245,158,11,.13);color:#FDBA45;border-color:rgba(245,158,11,.25)}
.kpi-icon-green{background:rgba(16,185,129,.13);color:#5DE0B3;border-color:rgba(16,185,129,.25)}
.kpi-icon-purple{background:rgba(155,109,255,.14);color:#BFA0FF;border-color:rgba(155,109,255,.26)}
.hf-kpi-link{transition:transform .16s ease,border-color .16s ease,box-shadow .16s ease}
.hf-kpi-link:hover{transform:translateY(-3px);border-color:#4D6897;box-shadow:0 20px 44px rgba(0,0,0,.25)}
.hf-chart-card{padding:22px;min-width:0}
.hf-chart-wrap{height:292px}
.hf-chart-wrap-small{height:252px}
.hf-chart-foot,.hf-data-note{color:#8FA1BA;font-size:11px;line-height:1.65}
.hf-insight-row{border-bottom-color:#26364D}
.hf-thumb{border-color:#344760;background:#142239}
.hf-thumb-empty{color:#99ACCA}
.hf-insight-row strong{color:#E5EDF8}
.hf-insight-row small{color:#8FA1BA}
.hf-insight-number{color:#EAF1FF}
.hf-toolbar{gap:10px}
.hf-table-wrap{border-color:#293951;border-radius:13px;background:#0E1829}
.hf-table{min-width:720px}
.hf-table th,.hf-table td{border-bottom-color:#26364D}
.hf-table th{
 background:#17243A;color:#91A4BF;letter-spacing:.085em;font-size:10px;
 box-shadow:0 1px 0 #2A3C55;
}
.hf-table td{font-size:12px;color:#CED9E9}
.hf-table strong{color:#E9F0FA}
.hf-table small{color:#90A1B9}
.hf-table tbody tr{transition:background .14s ease}
.hf-table tbody tr:hover td{background:#16243A}
.hf-status{background:#1B2940;color:#B7C5D9;border:1px solid #2E405A;font-size:10px;letter-spacing:.01em}
.hf-status-confirmed,.hf-status-delivered,.hf-status-published,.hf-status-active,.hf-status-visible{
 background:rgba(16,185,129,.13);color:#6EE7BE;border-color:rgba(16,185,129,.25)
}
.hf-status-processing,.hf-status-shipped,.hf-status-draft{
