.hf-funnel-fill{background:linear-gradient(90deg,#4F7CFF,#9B6DFF)}
.hf-funnel-label{color:#CBD7E8}
.hf-funnel-progress,.hf-progress-note{color:#91A3BC}
.hf-status-timeline-row:not(:last-child):before{background:#2A3D58}
.hf-status-timeline-dot{background:#6E8FFF;border-color:#263A60}
.hf-status-timeline-row p{color:#D7E1EF}
.hf-status-timeline-row small{color:#8EA1BB}
.hf-summary-pill{background:#0D182A;border-color:#293A53}
.hf-summary-pill small{color:#91A4BE}
.hf-summary-pill strong{color:#EFF4FF}
.hf-preference{border-bottom-color:#283850}
.hf-preference strong{color:#E2EAF6}
.hf-preference p{color:#93A5BD}
.help-content ol{color:#BCC9DA}
