.auth-gate-card{
 background:linear-gradient(145deg,#14213A,#10192A);
 border:1px solid #2C3E58;color:#E7EEF9;border-radius:20px;
 box-shadow:0 24px 80px rgba(0,0,0,.34);padding:32px;
}
