/* Overview priority action center — compact, scan-friendly guidance without new storage. */
.hf-action-center{margin-bottom:18px}
.hf-action-list{display:grid;gap:9px}
.hf-action-row{display:flex;align-items:center;gap:12px;padding:12px 13px;border:1px solid #293A53;border-radius:12px;background:#101B2D;min-width:0}
.hf-action-row.is-urgent{border-color:rgba(240,82,116,.34);background:rgba(240,82,116,.055)}
.hf-action-row.is-warning{border-color:rgba(245,158,11,.30);background:rgba(245,158,11,.045)}
.hf-action-count{display:grid;place-items:center;align-self:center;min-width:38px;min-height:38px;padding:0 8px;border-radius:11px;font-size:14px;font-weight:850;font-variant-numeric:tabular-nums;background:rgba(79,124,255,.13);color:#9BB6FF;flex:0 0 auto}
.hf-action-count.is-urgent{background:rgba(240,82,116,.14);color:#FFA0B3}
.hf-action-count.is-warning{background:rgba(245,158,11,.14);color:#FBC66A}
.hf-action-copy{flex:1 1 auto;min-width:0}
.hf-action-copy strong{display:block;font-size:12px;color:#EEF3FC}
.hf-action-copy p{margin:3px 0 0;color:#9AAAC0;font-size:11px;line-height:1.5}
.hf-action-link{flex:0 0 auto}
.hf-action-clear{display:flex;align-items:center;gap:12px;padding:14px;border:1px solid rgba(16,185,129,.26);border-radius:12px;background:rgba(16,185,129,.07)}
.hf-action-clear-icon{width:36px;height:36px;display:grid;place-items:center;border-radius:11px;background:rgba(16,185,129,.15);color:#6EE7BE;font-size:19px;font-weight:800;flex:0 0 auto}
.hf-action-clear strong{display:block;color:#C0F7E5;font-size:13px}
.hf-action-clear p{margin:3px 0 0;color:#98CDBB;font-size:11px;line-height:1.5}
#overviewActionCount{gap:5px}
#overviewActionCount strong{font-size:11px}
#overviewActionCount span{font-size:10px}
html[data-admin-theme="light"] .hf-action-row{background:#FFFDF8;border-color:#E5E0D6}
html[data-admin-theme="light"] .hf-action-row.is-urgent{background:#FFF6F5;border-color:#F2D0CA}
html[data-admin-theme="light"] .hf-action-row.is-warning{background:#FFFAF1;border-color:#F1DDB7}
html[data-admin-theme="light"] .hf-action-count{background:#EAF1FA;color:#416F9D}
html[data-admin-theme="light"] .hf-action-count.is-urgent{background:#FFECE8;color:#A33E32}
html[data-admin-theme="light"] .hf-action-count.is-warning{background:#FFF0D9;color:#98641C}
html[data-admin-theme="light"] .hf-action-copy strong{color:#2B2A3D}
html[data-admin-theme="light"] .hf-action-copy p{color:#737487}
html[data-admin-theme="light"] .hf-action-clear{background:#EDF8F0;border-color:#CDE6D5}
html[data-admin-theme="light"] .hf-action-clear-icon{background:#DDF1E3;color:#23744A}
html[data-admin-theme="light"] .hf-action-clear strong{color:#175130}
html[data-admin-theme="light"] .hf-action-clear p{color:#23633F}
@media(max-width:620px){
 .hf-action-row{align-items:flex-start;flex-wrap:wrap;gap:9px}
 .hf-action-count{min-width:34px;min-height:34px}
 .hf-action-copy{flex:1 1 calc(100% - 52px)}
 .hf-action-link{margin-left:43px}
}


/* Step 1 — shared dashboard shell: structured navigation, account menu and mobile drawer. */
.admin-sidebar{gap:18px;padding:23px 14px 16px;overscroll-behavior:contain;scrollbar-width:thin;scrollbar-color:#344760 transparent}
.admin-brand{flex:0 0 auto;gap:12px;padding:2px 10px 19px}
.admin-brand img{width:40px;height:40px;flex:0 0 40px}
.admin-brand-copy{min-width:0}
.admin-brand strong{font-size:15px;line-height:1.25}
.admin-brand small{font-size:10px;letter-spacing:.025em}
.admin-sidebar-nav{display:grid;gap:18px;min-width:0;padding:1px 0 8px}
.admin-nav-group{display:grid;gap:7px;min-width:0}
.admin-nav-label{padding:0 12px 3px;font-size:9px;letter-spacing:.15em;line-height:1.5}
.admin-nav-links{display:grid;gap:4px;min-width:0}
.admin-nav-link{min-width:0;min-height:40px;padding:8px 11px;gap:10px;border:1px solid transparent;border-radius:10px;font-size:12px;font-weight:600;line-height:1.35;transition:background .16s ease,border-color .16s ease,color .16s ease,transform .16s ease}
.admin-nav-link .nav-icon{width:20px;height:20px;flex:0 0 20px;display:grid;place-items:center;opacity:1}
.admin-nav-text{min-width:0;overflow-wrap:anywhere}
.hf-shell-icon{display:block;width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;flex:0 0 auto}
.admin-nav-link:hover{transform:translateX(2px)}
.admin-nav-link.active{font-weight:750}
.admin-sidebar-note{margin-top:auto;padding:12px 13px;display:grid;gap:6px}
.admin-sidebar-note-head{display:flex;align-items:center;gap:8px}
.admin-sidebar-note-head strong{margin:0;font-size:11px;line-height:1.4}
.admin-test-indicator{width:7px;height:7px;flex:0 0 7px;border-radius:50%;background:#E3AD58;box-shadow:0 0 0 3px rgba(227,173,88,.12)}
.admin-sidebar-note p{margin:0;font-size:10px;line-height:1.55;color:#A6B5C9}
.admin-frame{min-width:0;display:flex;flex-direction:column}
.admin-main{width:100%;flex:1 0 auto}
.admin-topbar{gap:12px;min-width:0}
.admin-menu-toggle{flex:0 0 40px;border-radius:11px}
.admin-global-search{min-width:0;flex:0 1 500px;max-width:500px}
.admin-global-search input{padding-left:41px;padding-right:70px}
.admin-global-search:before{content:none}
.admin-global-search-icon{position:absolute;left:13px;top:50%;transform:translateY(-50%);display:grid;place-items:center;color:#8395B0;pointer-events:none}
.admin-global-search-icon .hf-shell-icon{width:17px;height:17px}
.admin-global-search__shortcut{position:absolute;right:9px;top:50%;transform:translateY(-50%);display:inline-flex;align-items:center;gap:4px;padding:3px 5px;border:1px solid #34465F;border-radius:6px;background:#142239;color:#91A4BE;font:10px/1.3 Inter,"Segoe UI",sans-serif;white-space:nowrap;pointer-events:none}
.admin-global-search__shortcut b{font-weight:750;color:#CED9E9}
.admin-topbar-actions{display:flex;align-items:center;gap:7px;flex:0 0 auto}
.admin-topbar-actions .admin-top-button{display:inline-flex;align-items:center;justify-content:center;gap:7px}
.topbar-button-icon{display:grid;place-items:center;flex:0 0 17px}
.topbar-button-icon .hf-shell-icon{width:17px;height:17px}
.admin-mode-toggle .topbar-button-icon .hf-shell-icon{width:16px;height:16px}
.admin-account-menu{position:relative;flex:0 0 auto;min-width:0}
.admin-account-chip{list-style:none;display:flex;align-items:center;gap:9px;max-width:248px;min-height:42px;padding:3px 0 3px 12px;border:0;border-left:1px solid #2A3A53;border-radius:0;color:#E6EDF8;cursor:pointer;user-select:none}
.admin-account-chip::-webkit-details-marker{display:none}
.admin-account-chip::marker{content:""}
.admin-account-avatar{width:36px;height:36px;flex:0 0 36px;overflow:hidden;padding:0;border-radius:50%;display:grid;place-items:center;background:#20345A;color:#BFD0FF;border:1px solid #3A5387;font-size:12px;font-weight:800}
.admin-account-avatar-image{display:block;width:100%;height:100%;object-fit:cover}
.admin-account-avatar-fallback{display:grid;place-items:center;width:100%;height:100%}
.admin-account-meta{min-width:0;max-width:168px}
.admin-account-meta strong{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px;font-weight:750}
.admin-account-meta small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:10px;color:#899AB3}
.admin-account-chevron{display:grid;place-items:center;color:#93A4BC}
.admin-account-chevron .hf-shell-icon{width:15px;height:15px;transition:transform .16s ease}
.admin-account-menu[open] .admin-account-chevron .hf-shell-icon{transform:rotate(180deg)}
.admin-account-dropdown{position:absolute;right:0;top:calc(100% + 10px);z-index:100;width:min(300px,calc(100vw - 24px));padding:10px;border:1px solid #2C3E58;border-radius:15px;background:#111C2E;color:#E6EDF8;box-shadow:0 20px 55px rgba(0,0,0,.38)}
.admin-account-dropdown-head{display:grid;gap:4px;padding:10px 10px 13px;margin-bottom:6px;border-bottom:1px solid #283A53;min-width:0}
.admin-account-dropdown-kicker{font-size:9px;letter-spacing:.14em;font-weight:800;color:#8EA4C3}
.admin-account-dropdown-head strong{font-size:13px;overflow-wrap:anywhere;color:#F0F5FF}
.admin-account-dropdown-head small{font-size:11px;color:#92A4BD;overflow-wrap:anywhere}
.admin-account-settings-link,.admin-account-logout{display:flex;align-items:center;gap:10px;width:100%;min-height:40px;padding:9px 10px;border:1px solid transparent;border-radius:9px;font:600 12px/1.4 Inter,"Segoe UI",sans-serif;text-decoration:none;color:#D5E0EF;background:transparent;text-align:left;cursor:pointer}
.admin-account-settings-link .hf-shell-icon,.admin-account-logout .hf-shell-icon{width:17px;height:17px}
.admin-account-settings-link:hover{background:#1A2A43;color:#FFF;border-color:#30445F}
.admin-account-logout{margin-top:3px;color:#FFB8C6}
.admin-account-logout:hover{background:#351D2B;color:#FFD8E0;border-color:#693247}
.admin-sidebar-backdrop{display:block;position:fixed;inset:0;z-index:50;width:100%;height:100%;padding:0;margin:0;border:0;border-radius:0;background:rgba(2,7,16,.62);backdrop-filter:blur(2px);-webkit-backdrop-filter:blur(2px)}
.admin-sidebar-backdrop[hidden]{display:none!important}
body.admin-sidebar-open{overflow:hidden}
html[data-admin-theme="light"] .admin-account-chip{color:#2B2A3D;border-left-color:#E5E0D6}
html[data-admin-theme="light"] .admin-account-meta strong{color:#2B2A3D}
html[data-admin-theme="light"] .admin-account-meta small{color:#737487}
html[data-admin-theme="light"] .admin-account-avatar{background:#F1E3D5;color:#8A4C22;border-color:#E5D3BF}
