.admin-sidebar .admin-favorite-list{gap:5px}
.admin-sidebar .admin-favorites-empty{color:#687F8D !important}
.admin-sidebar .admin-nav-label{color:#3D6877 !important;text-shadow:0 1px 0 rgba(255,255,255,.32) !important}
.admin-sidebar .admin-nav-label:after{background:linear-gradient(90deg,rgba(62,117,132,.38),rgba(62,117,132,0)) !important}
/* Preserve the colorful menu buttons while softening their shadows. */
.admin-sidebar .admin-nav-link{box-shadow:0 3px 8px rgba(45,79,105,.075),inset 0 1px 0 rgba(255,255,255,.84) !important}
.admin-sidebar .admin-nav-link:hover{box-shadow:0 6px 12px rgba(45,79,105,.11),inset 0 1px 0 #FFFFFF !important}
