/* Header Theme Picker */
.hf-theme-control{position:relative;display:inline-flex;align-items:center}
.hf-theme-picker-trigger{gap:7px!important}
.hf-theme-picker-trigger .hf-theme-current-name{font-size:10px;font-weight:750;opacity:.82}
.hf-theme-picker-trigger .hf-theme-chevron{font-size:13px;margin-left:1px}
.hf-theme-picker{
 position:absolute;right:0;top:calc(100% + 12px);z-index:120;width:min(390px,calc(100vw - 32px));
 padding:15px;border:1px solid var(--hf-theme-border,#E3C6B1);border-radius:17px;
 background:var(--hf-theme-card-bg,#FFF4E8);color:var(--hf-theme-text,#654536);
 box-shadow:0 22px 60px rgba(44,35,28,.2),inset 0 1px 0 rgba(255,255,255,.72);
}
.hf-theme-picker[hidden]{display:none!important}
.hf-theme-picker-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:12px}
.hf-theme-picker-heading strong{display:block;font-size:14px;color:var(--hf-theme-text)}
.hf-theme-picker-heading p{margin:3px 0 0;font-size:11px;color:var(--hf-theme-muted)}
.hf-theme-picker-close{width:30px;height:30px;min-height:30px;padding:0;border:1px solid var(--hf-theme-border);border-radius:9px;background:var(--hf-theme-secondary);color:var(--hf-theme-text);font-size:19px;line-height:1}
.hf-theme-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
.hf-theme-option{
 position:relative;display:flex;align-items:center;gap:9px;min-width:0;padding:10px;
 border:1px solid var(--hf-theme-border);border-radius:12px;background:var(--hf-theme-control-bg);
 color:var(--hf-theme-text);text-align:left;cursor:pointer;transition:border-color .16s,background .16s,box-shadow .16s,transform .16s;
}
.hf-theme-option:hover{border-color:var(--hf-theme-primary);transform:translateY(-1px)}
.hf-theme-option.is-selected{border:2px solid var(--hf-theme-primary);background:var(--hf-theme-secondary);box-shadow:0 4px 12px color-mix(in srgb,var(--hf-theme-primary) 14%,transparent)}
.hf-theme-option-swatches{display:flex;flex-direction:column;gap:3px;flex:0 0 27px;width:27px}
.hf-theme-option-swatches i{display:block;height:7px;border-radius:4px;border:1px solid rgba(0,0,0,.06)}
.hf-theme-option-copy{display:grid;min-width:0;gap:2px}
.hf-theme-option-copy strong{font-size:11px;line-height:1.25}
.hf-theme-option-copy small{font-size:9px;color:var(--hf-theme-muted);line-height:1.25}
.hf-theme-option-check{display:none;margin-left:auto;flex:0 0 auto;font-weight:900;color:var(--hf-theme-primary)}
.hf-theme-option.is-selected .hf-theme-option-check{display:block}
.hf-theme-picker-footnote{margin:11px 2px 0;font-size:10px;color:var(--hf-theme-muted)}
@media(max-width:620px){
 .hf-theme-picker{position:fixed;top:74px;right:12px;left:12px;width:auto;max-height:calc(100dvh - 88px);overflow:auto;border-radius:16px}
 .hf-theme-picker-trigger .hf-theme-current-name{display:none}
 .hf-theme-grid{gap:7px}
 .hf-theme-option{padding:9px 8px}
}
@media(prefers-reduced-motion:reduce){.hf-theme-option{transition:none!important}}

/* Theme picker: business-oriented groups, clear focus and bounded scrolling. */
.hf-theme-picker{max-height:min(72vh,640px);overflow-y:auto;overscroll-behavior:contain}
.hf-theme-grid{display:grid;grid-template-columns:minmax(0,1fr);gap:13px}
.hf-theme-group{display:grid;gap:7px;min-width:0}
.hf-theme-group-heading{display:flex;align-items:baseline;justify-content:space-between;gap:10px;padding:0 2px}
.hf-theme-group-heading strong{font-size:11px;letter-spacing:.045em;color:var(--hf-theme-text)}
.hf-theme-group-heading small{font-size:9px;color:var(--hf-theme-muted);text-align:right}
.hf-theme-group-options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
.hf-theme-option:focus-visible{outline:3px solid var(--hf-theme-focus);outline-offset:2px}
@media(max-width:620px){
 .hf-theme-picker{max-height:calc(100dvh - 88px)}
 .hf-theme-group-options{gap:7px}
 .hf-theme-group-heading{align-items:flex-start;flex-direction:column;gap:1px}
 .hf-theme-group-heading small{text-align:left}
}

