ild{width:100%;padding:12px;border:0;border-radius:9px;background:#263b56;color:#fff;font-weight:800;cursor:pointer}.wp-auth-card button:disabled,.wp-preview-auth-card button:disabled{opacity:.55;cursor:wait}.wp-auth-reset{margin-top:10px;background:transparent!important;color:#80552f!important;text-decoration:underline}.wp-preview-auth{position:fixed;inset:0;z-index:2147483000;display:grid;place-items:center;padding:20px;background:rgba(15,23,42,.78);backdrop-filter:blur(8px);font-family:Inter,system-ui,sans-serif}.wp-preview-auth-card{width:min(420px,100%);box-sizing:border-box;padding:28px;border-radius:18px;background:#fff;color:#243247}.wp-preview-auth-card p{color:#64748b;font-size:13px;line-height:1.5}#wpAuthStatus{min-height:20px;color:#b42318}@media(max-width:700px){.wp-admin-shell{align-items:flex-start;flex-wrap:wrap;padding:12px}.wp-admin-shell nav{order:3;width:100%}.wp-admin-shell nav a{flex:1;text-align:center}.wp-admin-signout{margin-left:auto}}
