/* Independent WordPress Studio two-pane admin shell */
.wp-studio-layout{min-height:100vh;display:grid;grid-template-columns:258px minmax(0,1fr);background:#f7f5ef;color:#2b2a3d;font-family:Inter,system-ui,sans-serif}
