.wp-studio-nav{display:grid;gap:22px}.wp-studio-nav-group{display:grid;gap:5px}.wp-studio-nav-label{margin:0 10px 4px;color:#aaa8b8;font-size:9px;font-weight:850;letter-spacing:.15em}
