.wp-studio-nav-link:hover{background:#ffffff12;color:white}.wp-studio-nav-link.active{background:#ffffff1b;color:#fff;box-shadow:inset 3px 0 #c97b3d}
.wp-studio-nav-icon{width:22px;text-align:center;font-size:17px;color:#e5b48e}
.wp-studio-sidebar-foot{margin-top:auto;border:1px solid #ffffff22;background:#ffffff0b;border-radius:12px;padding:12px;color:#d6d3de;font-size:10px;line-height:1.5}
