.wp-studio-frame{min-width:0;min-height:100vh}.wp-studio-topbar{height:68px;display:flex;align-items:center;gap:13px;padding:10px clamp(16px,2.5vw,32px);background:#fffdf9;border-bottom:1px solid #e5e0d6;position:sticky;top:0;z-index:60}
